    a = [interval for interval in a if interval[0] < interval[1]]
    b = [interval for interval in b if interval[0] < interval[1]]

    # If nothing to subtract from, return empty
    if not a:
        return []

    # If nothing to subtract, return merged a
    if not b:
        return merge(a)

    # Merge intervals in a and b
    a_merged = merge(a)
    b_merged = merge(b)

    result = []

    for a_start, a_end in a_merged:
